/**
 * @summary Get daily summary report
 */
export const getGetDailyReportUrl = (
  schoolId: number,
  params: GetDailyReportParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/schools/${schoolId}/reports/daily?${stringifiedParams}`
    : `/api/schools/${schoolId}/reports/daily`;
};

export const getDailyReport = async (
  schoolId: number,
  params: GetDailyReportParams,
  options?: RequestInit,
): Promise<DailyReport> => {
  return customFetch<DailyReport>(getGetDailyReportUrl(schoolId, params), {
    ...options,
    method: "GET",
  });
};

export const getGetDailyReportQueryKey = (
  schoolId: number,
  params?: GetDailyReportParams,
) => {
  return [
    `/api/schools/${schoolId}/reports/daily`,
    ...(params ? [params] : []),
  ] as const;
};

